import{_ as a,o as t,c as i,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-09-23 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-09-23 :: Ceph Orchestration Meeting","date":"2019-09-23T00:00:00.000Z","updated":"2019-10-01T00:00:00.000Z","tags":["Ceph","Orchestrator","Rook","Distributed Storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-09-23_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-09-23_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2019/2019-09-23_-_-_Ceph_Orchestration_Meeting.md"};function r(s,o,n,h,_,d){return t(),i("div",null,[...o[0]||(o[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>与会人员</strong>： Kifa、Recovery、Travis、Fashion Wagner、Sebastian Hunt、Adam（Red Hat）、其他团队成员</p><p><strong>会议主题</strong>： Orchestrator项目进展、Rook CI、Rook 1.1.1发布、Ceph集群管理、Rook操作工具等</p><h3 id="会议关键细节" tabindex="-1">会议关键细节 <a class="header-anchor" href="#会议关键细节" aria-label="Permalink to &quot;会议关键细节&quot;">​</a></h3><ul><li><strong>OSD创建与平衡</strong>： <ul><li>讨论了OSD创建过程中可能产生的大量流量问题，提出了将新添加的OSD权重设置为0的方案，以便平衡器可以逐步将其映射到crash map。</li><li>决定不将此功能设置为默认行为，需要用户手动调整权重。</li></ul></li><li><strong>Dashboard中的驱动器组创建</strong>： <ul><li>讨论了Dashboard创建驱动器组的需求，需要Rook提供正确的卷库存信息。</li><li>决定在Dashboard中实现创建驱动器组的功能，但需要Rook提供安全卷库存。</li><li>讨论了保留两种发现机制以避免破坏现有功能。</li></ul></li><li><strong>Rook CI</strong>： <ul><li>讨论了Rook CI的长期计划，并计划下周三进行社区电话会议。</li><li>由于Adam（Red Hat）的休假，会议时间需要调整。</li></ul></li><li><strong>Rook 1.1.1发布</strong>： <ul><li>介绍了Rook 1.1.1的发布，其中包含许多修复和稳定性改进。</li><li>讨论了Rook 1.1.2的发布计划。</li></ul></li><li><strong>Rook操作工具</strong>： <ul><li>讨论了Rook操作工具的改进，包括如何处理在未安装任何软件的宿主机上运行脚本的情况。</li><li>决定使用简单的脚本，并尽量保持其可读性和简洁性。</li></ul></li></ul><h3 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h3><ul><li>不将OSD自动添加到crash map的默认行为。</li><li>在Dashboard中实现创建驱动器组的功能，需要Rook提供安全卷库存。</li><li>下周三进行Rook CI社区电话会议，时间待定。</li><li>发布Rook 1.1.2。</li><li>改进Rook操作工具。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>Kifa继续进行OSD创建和平衡的改进。</li><li>Recovery继续进行Dashboard驱动器组创建的实现。</li><li>Adam（Red Hat）和团队继续进行Rook CI的改进。</li><li>Travis和团队继续进行Rook 1.1.2的发布。</li><li>Fashion Wagner和Sebastian Hunt继续进行Rook操作工具的改进。</li></ul><p>[改进后的内容保留了会议的关键细节，讨论的主要议题，决定的事项以及后续的行动计划，并确保了计算机科学/ceph相关领域的英文原文关键词得以保留]。</p>',12)])])}const u=a(l,[["render",r]]);export{c as __pageData,u as default};
